// Generates src/features/student/bus/leafletAssets.generated.ts from the installed `leaflet` package (devDependency), so the student map ships Leaflet
// INSIDE the app: no CDN, no network request for the library, and the page works the moment the WebView starts.
// Run after changing the leaflet version:  npm run build:leaflet   (then commit the generated file).
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'node_modules', 'leaflet', 'dist');
const pkg = JSON.parse(readFileSync(join(root, 'node_modules', 'leaflet', 'package.json'), 'utf8'));
const js = readFileSync(join(dist, 'leaflet.js'), 'utf8');
// the stylesheet points at marker / layer images we never use (divIcon markers, no layer control): drop the url() so nothing tries to load them
const css = readFileSync(join(dist, 'leaflet.css'), 'utf8').replace(/url\((?:images\/)[^)]*\)/g, 'none');

const out = `// GENERATED by scripts/build-leaflet-assets.mjs from leaflet@${pkg.version} (BSD-2-Clause, https://leafletjs.com). Do not edit by hand.
export const LEAFLET_VERSION = ${JSON.stringify(pkg.version)};
export const LEAFLET_JS = ${JSON.stringify(js)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
`;
writeFileSync(join(root, 'src', 'features', 'student', 'bus', 'leafletAssets.generated.ts'), out);
console.log(`leaflet@${pkg.version}: ${js.length} bytes of JS, ${css.length} bytes of CSS written`);
